        {/if}
        {capture $c_4}
          {=og_text(og_get($v_line, ['text']))}
        {/capture}
        {=og_include('compose/Inline.latte', ['children' => (string) $c_4])|noescape}
      {/capture}
      {=og_include('compose/ListItem.latte', ['class' => og_s(og_cnv(['flex gap-2', (og_t(og_eq(og_get($v_line, ['kind']), 'command')) ? 'text-foreground' : 'text-muted-foreground')])), 'attrs' => og_attrs(['data-kind', og_get($v_line, ['kind'])]), 'children' => (string) $c_5])|noescape}
    {/foreach}
  {/capture}
